import{_ as o,o as a,c as t,a0 as s}from"./chunks/framework.OED5XGjC.js";const m=JSON.parse('{"title":"Release model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/release-model.md","filePath":"explanation/release-model.md"}'),c={name:"explanation/release-model.md"};function i(r,e,d,l,n,h){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="release-model" tabindex="-1">Release model <a class="header-anchor" href="#release-model" aria-label="Permalink to &quot;Release model&quot;">​</a></h1><blockquote><p>User-facing install is the tamias pack (<code>libraries/myco</code> → <code>tamias install 9aia:myco@&lt;ver&gt;</code>); the <code>myco</code> crates are lib-only engines behind <code>tamias-driver-myco</code> — there is no cargo-installed <code>myco</code> binary and <strong>no crates.io publish</strong> (org policy keeps every repo but tamias off crates.io; the <code>myco</code> name there is held by an unrelated project, and path deps like <code>myco-store-md</code> were never published). This page describes the tag release pipeline that feeds the pack.</p></blockquote><p>Releases are manual: <code>scripts/release.sh</code> is run by an operator on <code>main</code>. The script&#39;s leading debounce window (default 5 min, <code>MYCO_RELEASE_DEBOUNCE</code>) still applies, and it pushes commits and tags to <code>main</code>.</p><p>The org release plane is <strong>tarsi</strong> (<code>tarsi-serve</code> ops — project ADR-0005): <code>scripts/release.sh</code> is being converted to a thin shim over it (PL-014 E1), and until then this script implements the same tag-only + <code>tamias publish</code> model directly.</p><h2 id="what-a-release-run-does" tabindex="-1">What a release run does <a class="header-anchor" href="#what-a-release-run-does" aria-label="Permalink to &quot;What a release run does&quot;">​</a></h2><ol><li><strong>Diff since the last tag</strong> — release-worthy paths are the workspace crates (<code>crates/</code>), the tamias pack payload (<code>libraries/</code>), <code>xtask/</code>, the workspace manifests/lockfile, and the release script itself. Changes to anything else trigger nothing. No release-set changes, no release.</li><li><strong>Workspace version bump</strong> — every crate inherits <code>version.workspace</code>, so <code>cargo set-version --workspace --bump patch</code> moves them all at once and rewrites the <code>workspace.dependencies</code> version reqs and <code>Cargo.lock</code> together. The script then syncs the user-facing version refs: <code>libraries/myco/tamias.yaml</code> (<code>version:</code>) and the install examples in <code>README.md</code> and <code>.agents/skills/myco/SKILL.md</code> (<code>myco@&lt;ver&gt;</code>).</li><li><strong>Commit + tag + push</strong> — one <code>release: bump myco to &lt;ver&gt;</code> commit, tagged <code>myco-v&lt;ver&gt;</code>, pushed to <code>main</code> with the tag.</li><li><strong>Pack publish (operator)</strong> — the script prints the follow-up: <code>tamias publish libraries/myco</code> ships <code>9aia:myco@&lt;ver&gt;</code> to the org registry (needs <code>TAMIAS_REGISTRY_TOKEN</code>). That step is deliberately outside the script — publishing is a credentials-gated, registry-side action.</li></ol><p>With no tags at all the script exits early — the flow is seeded by tagging once.</p><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h2><ul><li>There is no crates.io publish path and no per-crate tag scheme — the whole workspace shares one version and one <code>myco-v&lt;ver&gt;</code> tag.</li><li>Only the tamias pack is user-facing; <code>myco-tui</code>&#39;s standalone binary and <code>tamias-driver-myco</code> are dev conveniences installed via <code>cargo xtask install</code>, not release artifacts.</li><li>Prebuilt binary distribution (GitHub Releases + cargo-dist — <code>dist-workspace.toml</code> is configured but idle) is a future option tracked as T-041, not part of the release flow.</li></ul><h2 id="ci-and-docs-deploys" tabindex="-1">CI and docs deploys <a class="header-anchor" href="#ci-and-docs-deploys" aria-label="Permalink to &quot;CI and docs deploys&quot;">​</a></h2><p>There are no GitHub Actions workflows; the gate is the peregrin <code>ci-gate</code> campaign (the gate is mid-migration back to bupha):</p><ul><li><strong>Push to <code>docs</code></strong> runs <code>scripts/deploy-docs.sh</code>, which rebuilds the site and pushes <code>gh-pages</code> — Pages is a legacy branch deploy, so that push is the whole release of the site.</li><li><strong>Push to <code>main</code></strong> is gated by the ci-gate campaign (<code>scripts/ci.sh</code> = <code>check &amp;&amp; test</code> + the coverage floor) and locally by the <code>pre-push</code> hook (<code>cargo xtask check</code>).</li></ul>',12)])])}const g=o(c,[["render",i]]);export{m as __pageData,g as default};
